from cardio_1 import a, G
a('NICE', [('N', 'National'), ('I', 'Institute for Health and'), ('C', 'Care'), ('E', 'Excellence')], 'Institut national britannique pour l’excellence en santé et en soins', '<p>Organisme britannique qui publie notamment NG120, référentiel de prise en charge de la toux aiguë. Ses schémas ne remplacent pas les recommandations locales suisses.</p>')
a('NG120', [('NG', 'NICE Guideline'), ('120', 'numéro 120')], 'Recommandation NICE 120 sur la toux aiguë', '<p>Référentiel publié en 2019 : évolution, réévaluation et antibiothérapie de la toux aiguë. Utilisé dans le cours J40 — Bronchite.</p>')
a('NLM', [('N', 'National'), ('L', 'Library of'), ('M', 'Medicine')], 'Bibliothèque nationale de médecine des États-Unis', '<p>Organisme qui maintient notamment le vocabulaire médical MeSH et héberge PubMed. Le descripteur de bronchite chronique documente la définition clinique classique du syndrome.</p>')
a('CDC', [('C', 'Centers for'), ('D', 'Disease'), ('C', 'Control and Prevention')], 'Centres américains de contrôle et de prévention des maladies', '<p>Organisme de santé publique : recommandations de soins ambulatoires et de prise en charge de la coqueluche. Les recommandations ne remplacent pas l’évaluation du patient ni un protocole local.</p>')
for code, title in [('J41.0', 'Bronchite chronique simple'), ('J41.1', 'Bronchite chronique mucopurulente'), ('J41.8', 'Bronchite chronique simple et mucopurulente')]:
    a(code, [(code, 'code CIM-10-GM')], title, '<p>Variante développée dans le cours unique J40 — Bronchite. Ce code ne confirme pas, à lui seul, une obstruction de BPCO.</p>')
